userscript.function:

	$sObject._vp[0].parentElement.classList.add("sepoa_form_label_top");

    CodeMirror.commands.autocomplete = function(cm) {
        cm.showHint({hint: CodeMirror.hint.javascript});
    }

    var codeMode = "javascript"
    if(Sepoa.params.options && Sepoa.params.options.script){
        if(Sepoa.params.options.script.type == 'link'){
            codeMode = "text/xml"
        }else if(Sepoa.params.options.script.type == 'css'){
            codeMode = "css"
        }
    }

    formObj_S = $sObject.formObj_S = new SepoaMultiDhtmlXFormObject(tabbarDiv, 'formObj_S', [Sepoa.params.form.script])
    formObj_S.forEachItem(function(obj, name){
        if(name.indexOf("EDITOR_") == 0){
            codeObj = $sObject.codeObj = CodeMirror(obj.getContainer(name), {
                lineNumbers: true,
                theme:"default",
                viewportMargin:0,
                indentUnit:4,
                extraKeys:{"Ctrl-Q":"toggleComment","Ctrl-Space": "autocomplete"},
                mode:codeMode
            });

            codeObj.on("change", function(obj, e) {
            	if(obj.getValue().trim().length <= 0) {
            		formObj_S.setValue('TEMPLATE_TYPE', '');
            		formObj_S.setReadonly('TEMPLATE_TYPE', false);
            	} else {
            		formObj_S.setReadonly('TEMPLATE_TYPE', true);
            	}
            });
        }
    })
    formObj_S.attachEvent("onBeforeChange", function (name, oValue, nValue){
        if(name == "NAME"){
            for(var i in Sepoa.params.script){
                if((["function","var"].indexOf(Sepoa.params.script[i].type) + 1) && Sepoa.params.script[i].NAME == nValue){
                    Alert(Sepoa.cache.text.get('SCREEN_BUILDER_MOCKUP_POPUP.MESSAGE_0002'));
                    return false;
                }
            }
        }
        return true;
    });

    formObj_S.attachEvent("onChange", function(name, value){
        if(name == "TYPE"){
            formObj_S.hideItem('NAME');
            formObj_S.hideItem('ARGS');
            formObj_S.hideItem('EDITOR_VALUE');
            formObj_S.hideItem('CALLBACK_TYPE');
            formObj_S.hideItem('CALLBACK');
            formObj_S.hideItem('OBJECT');
            formObj_S.hideItem('TEMPLATE_TYPE');

            if(value == "call"){
                formObj_S.showItem('NAME');
                formObj_S.showItem('ARGS');
            }else if(value == "function"){
                formObj_S.showItem('NAME');
                formObj_S.showItem('ARGS');
                formObj_S.showItem('TEMPLATE_TYPE');
                formObj_S.showItem('EDITOR_VALUE');
            }else if(value == "var"){
                formObj_S.showItem('NAME');
                formObj_S.showItem('EDITOR_VALUE');
            }else if(value == "event"){
                formObj_S.showItem('NAME');
                formObj_S.showItem('OBJECT');
                formObj_S.showItem('CALLBACK_TYPE');
                formObj_S.callEvent('onChange', ['CALLBACK_TYPE', formObj_S.getValue('CALLBACK_TYPE')])
            }else if(["link", "text", "css"].indexOf(value) + 1){
                formObj_S.showItem('EDITOR_VALUE');
            }
            setSize();
        }else if(name == "CALLBACK_TYPE"){
            if(value == "function"){
                formObj_S.showItem('ARGS');
                formObj_S.showItem('EDITOR_VALUE');
                formObj_S.hideItem('CALLBACK');
            }else{
                formObj_S.hideItem('ARGS');
                formObj_S.hideItem('EDITOR_VALUE');
                formObj_S.showItem('CALLBACK');
            }
            setSize();
        }else if(name == "TEMPLATE_TYPE") {
        	var codeData = codeObj.getValue().trim();

        	if( codeData.length <= 0 ) {
        		codeObj.setValue(value);
        	}
        }
    })

    if(Sepoa.params.options && Sepoa.params.options.script){
        formObj_S.dataMapper(Sepoa.params.options.script, "json")
        formObj_S.setValue("ARGS", formObj_S.getValue("ARGS").replaceAll("&#39;","'"))
        formObj_S.callEvent('onChange', ['TYPE', formObj_S.getValue('TYPE')])

        if(Sepoa.params.options.script.type == "event"){
            var callback = Sepoa.params.options.script.CALLBACK
            if(callback && !(typeof(callback) == "string")){
                formObj_S.setValue("CALLBACK_TYPE", "function");
                formObj_S.setValue("ARGS", callback.ARGS);
                formObj_S.setValue("CALLBACK", '');
                codeObj.setValue(callback.VALUE.replaceAll("&#39;","'"));

                CodeMirror.commands.selectAll(codeObj);
                var range = { from: codeObj.getCursor(true), to: codeObj.getCursor(false) };
                codeObj.autoFormatRange(range.from, range.to);
                CodeMirror.commands.goDocEnd(codeObj);
            }
            formObj_S.callEvent('onChange', ['CALLBACK_TYPE', formObj_S.getValue('CALLBACK_TYPE')]);
        }else if(Sepoa.params.options.script.type = "link"){
            if(Sepoa.params.options.script["VALUE"]){
                codeObj.setValue(Sepoa.params.options.script["VALUE"].replaceAll("&#39;","'"));
            }
        }else if(Sepoa.params.options.script.type != "call"){
            if(Sepoa.params.options.script["VALUE"]){
                codeObj.setValue(Sepoa.params.options.script["VALUE"].replaceAll("&#39;","'"));

                CodeMirror.commands.selectAll(codeObj);
                var range = { from: codeObj.getCursor(true), to: codeObj.getCursor(false) };
                codeObj.autoFormatRange(range.from, range.to);
                CodeMirror.commands.goDocEnd(codeObj);
            }
        }
    }else{
        formObj_S.callEvent('onChange', ['TYPE', formObj_S.getValue('TYPE')])
    }

    setSize();

    SUX.callEvent('onWindowResize', []);


if(id == 'CANCEL'){
    selfObj.close();
}else if(id == 'SAVE'){

	if(!formObj_S.validateItem("EDITOR_VALUE")) {
		Alert(Sepoa.cache.text.get("MESSAGE.0002"));
		return;
	}

    var so = {message:"", status:true};
    var formData = formObj_S.getFormData();
    var r = {
        type:formData.TYPE
    }
    if(Sepoa.params.options && Sepoa.params.options.script){
        r.id=Sepoa.params.options.script.id
    }

    formData.VALUE = codeObj.getValue();

    switch(formData.TYPE){
    case 'event':
        r.NAME  = formData.NAME;
        r.CALLBACK_TYPE = formData.CALLBACK_TYPE
        r.OBJECT = formData.OBJECT
        if(formData.CALLBACK_TYPE == 'function'){
            r.CALLBACK = {
                ARGS:formData.ARGS,
                VALUE:formData.VALUE
            }
        }else{
            r.CALLBACK = formData.CALLBACK
        }
        break;
    case 'function':
        r.NAME  = formData.NAME;
        r.ARGS  = formData.ARGS;
        r.VALUE = formData.VALUE;
        break;
    case 'call':
        r.NAME = formData.NAME;
        r.ARGS = formData.ARGS;
        break;
    case 'text':
    case 'link':
    case 'css':
        r.VALUE = formData.VALUE;
        break;
    case 'var':
        r.NAME  = formData.NAME;
        r.VALUE = formData.VALUE;
        break;
    }

    var so = {message:"", status:true};
    Sepoa.params.callback.apply(Sepoa.params.callObj, [r]);

    if(so.status){
        selfObj.close();
    }else{
        Alert(so.message);
    }
}


var s = {width:400, height:500}

var tArray = [formObj_S]
for(var i in tArray){
    var t = tArray[i];
    if(t){
        var c = t._parent.children[0]
        var w = c.offsetWidth + 110;
        var h = c.offsetHeight + 180;
        if(w > s.width) s.width = w;
        if(h > s.height) s.height = h;
    }
}

selfObj[selfObj.name].setDimension(s.width, s.height);
selfObj[selfObj.name].center();
